steps.script:
var board: Dictionary = GameState.create_snapshot()
var plain: Dictionary = board.duplicate(true)
for k in ["waaagh_active", "effect_invuln", "effect_invuln_source", "effect_advance_and_charge", "effect_advance_and_shoot", "waaagh_assault_granted"]:
	plain.units.U_DEFF_DREAD_A.flags.erase(k)
var act := {"type": "FIGHT", "actor_unit_id": "U_DEFF_DREAD_A", "payload": {"assignments": [{"attacker": "U_DEFF_DREAD_A", "target": "U_PROSECUTORS_A", "weapon": "Dread Klaws"}]}}
var out := []
for b in [board, plain]:
	RulesEngine.set_test_seed(555)
	var res = RulesEngine.resolve_melee_attacks(act, b.duplicate(true), RulesEngine.RNGService.new())
	var hits := -1
	var s := -1
	for d in res.get("dice", []):
		if str(d.get("context", "")) == "hit_roll_melee":
			hits = (d.get("rolls_raw", d.get("rolls", [])) as Array).size()
		elif str(d.get("context", "")) in ["wound_roll_melee", "to_wound_melee", "wound_roll"]:
			s = int(d.get("strength", -1))
	out.append([hits, s])
return out[0] == out[1] and out[0][0] > 0
